6	pub use parser::{Modifier, ParsedTerm, parse};
7	pub use plan::QueryPlan;
8	
9	#[cfg(test)]
10	mod tests {
11	    #[test]
12	    fn reexported_items_reachable_at_query_root() {
13	        use crate::query::{Modifier, ParsedTerm, QueryPlan, parse};
14	        let terms: Vec<ParsedTerm> = parse("+foo").unwrap();
15	        assert_eq!(terms.len(), 1);
16	        assert_eq!(terms[0].modifier, Modifier::Required);
17	        let qp = QueryPlan::from_terms(terms);
18	        assert_eq!(qp.required, vec![0]);
19	    }
20	
21	    #[test]
22	    fn lexer_and_token_only_reachable_via_query_lexer_path() {
23	        use crate::query::lexer::{Lexer, Token};
24	        let mut l = Lexer::new("foo");
25	        assert_eq!(l.next_token(), Token::Word("foo".to_string()));
26	    }
27	
28	    // Reachability tests cannot detect an extra re-export, such as `pub type Token = lexer::Token;`, so this compares
29	    // every non-comment line before the test module against the exact expected declarations.
30	    #[test]
31	    fn mod_rs_exact_reexport_surface_structural() {
32	        let src = include_str!("mod.rs");
33	        // The test module has its own `use` and `mod` lines, so only the part before it is compared.
34	        let head = &src[..src.find("#[cfg(test)]").expect("no test module marker found in mod.rs")];
35	
36	        let head_lines: Vec<&str> =
37	            head.lines().map(str::trim).filter(|l| !l.is_empty() && !l.starts_with("//")).collect();
38	        assert_eq!(
39	            head_lines,
40	            vec![
41	                "pub mod lexer;",
42	                "pub mod parser;",
43	                "pub mod plan;",
44	                "pub use parser::{Modifier, ParsedTerm, parse};",
45	                "pub use plan::QueryPlan;",
46	            ],
47	            "mod.rs's pre-test portion must contain exactly these 5 declarations, in this exact order, and nothing else"
48	        );
49	    }
50	}
