64	fn a_query_with_no_match_prints_an_empty_result() {
65	    let output = monokl(&["search", "zzzqqqxx", "."]);
66	    assert!(output.status.success());
67	    assert!(stdout(&output).starts_with("search: []"), "got: {}", stdout(&output));
