70	#[test]
71	fn an_invalid_regex_fails_with_a_structured_error() {
72	    let output = monokl(&["search", "regex:(", "."]);
73	    assert_eq!(output.status.code(), Some(1));
74	    assert_eq!(stdout(&output), "");
