1	use camino::{Utf8Path, Utf8PathBuf};
2	use proptest::prelude::*;
3	
4	use super::*;
5	
6	const KINDS: [SymbolKind; 15] = [
7	    SymbolKind::Function,
8	    SymbolKind::Method,
9	    SymbolKind::Constructor,
10	    SymbolKind::Class,
11	    SymbolKind::Struct,
12	    SymbolKind::Enum,
13	    SymbolKind::Interface,
14	    SymbolKind::TypeAlias,
15	    SymbolKind::Property,
16	    SymbolKind::Field,
17	    SymbolKind::Variable,
18	    SymbolKind::Module,
19	    SymbolKind::Impl,
20	    SymbolKind::Macro,
21	    SymbolKind::Other,
22	];
23	
24	const TERMS: [&str; 3] = ["user", "name", "foo"];
25	
26	fn input_block() -> impl Strategy<Value = (CodeBlock, Vec<String>)> {
27	    (
28	        prop::sample::select(vec!["a.ts", "a.b.ts", "a/z.ts", "b.ts"]),
29	        0usize..4,
30	        0usize..4,
31	        prop::sample::select(KINDS.to_vec()),
32	        prop::sample::select(vec!["", "a()", "b()"]),
33	        prop::collection::vec(0usize..6, 0..3),
34	        prop::collection::vec(prop::sample::select(vec!["user", "name", "foo", "other"]), 0..5),
35	    )
36	        .prop_map(|(file, line_start, line_end, node_kind, code, matched_lines, tokens)| {
37	            let block = CodeBlock {
38	                file: Utf8PathBuf::from(file),
39	                line_start,
40	                line_end,
41	                node_kind,
42	                code: code.to_string(),
43	                symbol_signature: None,
44	                matched_lines,
45	                matched_keywords: Vec::new(),
46	            };
47	            (block, tokens.into_iter().map(String::from).collect())
48	        })
49	}
50	
51	fn df_strategy() -> impl Strategy<Value = HashMap<String, usize>> {
52	    prop::collection::vec(0usize..8, TERMS.len())
53	        .prop_map(|counts| TERMS.iter().map(ToString::to_string).zip(counts).collect())
54	}
55	
56	fn terms_strategy() -> impl Strategy<Value = Vec<&'static str>> {
57	    prop::collection::vec(prop::sample::select(TERMS.to_vec()), 0..4)
58	}
59	
60	fn components(path: &Utf8Path) -> Vec<&str> {
61	    path.components().map(|c| c.as_str()).collect()
62	}
63	
64	/// Whether `a` sorts strictly before `b`, written out key by key rather than as a comparator chain.
65	fn precedes(a: &RankedBlock, b: &RankedBlock) -> bool {
66	    // Adding 0.0 turns -0.0 into 0.0.
67	    let (score_a, score_b) = (a.final_score + 0.0, b.final_score + 0.0);
68	    if score_a.total_cmp(&score_b).is_ne() {
69	        return score_a.total_cmp(&score_b).is_gt();
70	    }
71	    sort_keys(a) < sort_keys(b)
72	}
73	
74	fn sort_keys(r: &RankedBlock) -> (Vec<&str>, usize, usize, Option<usize>, &str) {
75	    let kind = KINDS.iter().position(|k| *k == r.block.node_kind);
76	    (components(&r.block.file), r.block.line_start, r.block.line_end, kind, &r.block.code)
77	}
78	
79	/// Selection sort that always takes the earliest minimal element, so equal blocks keep their relative order.
80	fn reference_order(mut pool: Vec<RankedBlock>) -> Vec<RankedBlock> {
81	    let mut out = Vec::new();
82	    while !pool.is_empty() {
83	        let mut best = 0;
84	        for idx in 1..pool.len() {
85	            if precedes(&pool[idx], &pool[best]) {
86	                best = idx;
87	            }
88	        }
89	        out.push(pool.remove(best));
90	    }
91	    for (rank, block) in (1..).zip(&mut out) {
92	        block.rank = rank;
93	    }
94	    out
95	}
96	
97	/// Identity of an input block, ignoring everything the ranker computes.
98	fn identity(b: &CodeBlock) -> (String, usize, usize, usize, String, Vec<usize>) {
99	    let kind = KINDS.iter().position(|k| *k == b.node_kind).unwrap_or(usize::MAX);
100	    (b.file.to_string(), b.line_start, b.line_end, kind, b.code.clone(), b.matched_lines.clone())
101	}
102	
103	/// The six sort keys plus rank. Blocks equal on all six are indistinguishable here, so their relative order is free.
104	fn full_key(r: &RankedBlock) -> (String, usize, usize, usize, String, u64, usize) {
105	    let b = &r.block;
106	    let kind = KINDS.iter().position(|k| *k == b.node_kind).unwrap_or(usize::MAX);
107	    (b.file.to_string(), b.line_start, b.line_end, kind, b.code.clone(), r.final_score.to_bits(), r.rank)
108	}
109	
110	proptest! {
111	    #[test]
112	    fn rank_blocks_matches_the_naive_reference(
113	        blocks in prop::collection::vec(input_block(), 0..12),
114	        terms in terms_strategy(),
115	        df in df_strategy(),
116	    ) {
117	        let ranked = rank_blocks(blocks.clone(), &terms, &df);
118	        prop_assert_eq!(ranked.len(), blocks.len());
119	
120	        // The reference sorts the ranker's own scored blocks; scoring itself is covered by score tests.
121	        let mut input_ids: Vec<_> = blocks.iter().map(|(b, _)| identity(b)).collect();
122	        let mut output_ids: Vec<_> = ranked.iter().map(|r| identity(&r.block)).collect();
123	        input_ids.sort();
124	        output_ids.sort();
125	        prop_assert_eq!(output_ids, input_ids);
126	
127	        let mut scrambled: Vec<RankedBlock> = ranked.iter().rev().cloned().collect();
128	        for r in &mut scrambled {
129	            r.rank = 0;
130	        }
131	        let expected = reference_order(scrambled);
132	        prop_assert_eq!(ranked.iter().map(full_key).collect::<Vec<_>>(), expected.iter().map(full_key).collect::<Vec<_>>());
133	    }
134	
135	    #[test]
136	    fn rank_blocks_ignores_input_order_when_no_blocks_tie(
137	        blocks in prop::collection::vec(input_block(), 0..12),
138	        terms in terms_strategy(),
139	        df in df_strategy(),
140	        seed in any::<u64>(),
141	    ) {
142	        let key = |b: &CodeBlock| (b.file.clone(), b.line_start, b.line_end, KINDS.iter().position(|k| *k == b.node_kind), b.code.clone());
143	        let mut keys: Vec<_> = blocks.iter().map(|(b, _)| key(b)).collect();
144	        keys.sort();
145	        keys.dedup();
146	        prop_assume!(keys.len() == blocks.len());
147	
148	        let mut shuffled = blocks.clone();
149	        // Deterministic Fisher-Yates driven by a splitmix-style generator, so failures replay from the seed alone.
150	        let mut state = seed;
151	        for idx in (1..shuffled.len()).rev() {
152	            state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
153	            let mut z = state;
154	            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
155	            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
156	            let pick = usize::try_from((z ^ (z >> 31)) % (idx as u64 + 1)).unwrap_or(0);
157	            shuffled.swap(idx, pick);
158	        }
159	
160	        let original = rank_blocks(blocks, &terms, &df);
161	        let permuted = rank_blocks(shuffled, &terms, &df);
162	        prop_assert_eq!(original.iter().map(full_key).collect::<Vec<_>>(), permuted.iter().map(full_key).collect::<Vec<_>>());
163	    }
164	}
