5	fn assert_well_formed(tokens: &[String]) -> Result<(), TestCaseError> {
6	    for token in tokens {
7	        prop_assert!(token.len() >= 2, "short token {token:?}");
8	        prop_assert!(
9	            token.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit()),
10	            "token {token:?} is not lowercase ASCII alphanumeric"
11	        );
12	        prop_assert!(!STOP_WORDS.contains(&token.as_str()), "stop word {token:?}");
13	    }
14	    let joined = tokens.concat();
15	    prop_assert!(joined.chars().all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit()), "separator in {joined:?}");
16	    Ok(())
17	}
18	
