21	    fn tokenize_yields_only_lowercase_alphanumeric_non_stop_words(input in "\\PC{0,40}") {
22	        assert_well_formed(&tokenize(&input))?;
23	    }
24	
25	    #[test]
26	    fn tokenize_source_yields_only_lowercase_alphanumeric_non_stop_words(input in "[ -~\\n\u{e9}\u{65e5}]{0,60}") {
27	        assert_well_formed(&tokenize_source(&input))?;
28	    }
