1	use proptest::prelude::*;
2	
3	use super::*;
4	
5	/// A term as the user would write it: the text before escaping, so that a literal's `pattern` is its escape.
6	#[derive(Debug, Clone)]
7	enum Written {
8	    Literal(Modifier, String),
9	    Regex(String),
10	}
11	
12	// No backslash: `\"` is the only escape, so a backslash next to a quote has no faithful rendering.
13	fn text() -> impl Strategy<Value = String> {
14	    "[a-zA-Z0-9 .*+?()\\[\\]{}|^$:\"-]{0,12}"
15	}
16	
17	fn written() -> impl Strategy<Value = Written> {
18	    prop_oneof![
19	        (prop_oneof![Just(Modifier::Required), Just(Modifier::Excluded), Just(Modifier::Optional)], text())
20	            .prop_map(|(modifier, text)| Written::Literal(modifier, text)),
21	        // A modifier before `regex:` is dropped by the parser, so a regex term is always optional.
22	        text().prop_map(Written::Regex),
23	    ]
24	}
25	
26	fn render(terms: &[Written]) -> String {
27	    let quote = |text: &str| format!("\"{}\"", text.replace('"', "\\\""));
28	    let rendered: Vec<String> = terms
29	        .iter()
30	        .map(|term| match term {
31	            Written::Literal(Modifier::Required, text) => format!("+{}", quote(text)),
32	            Written::Literal(Modifier::Excluded, text) => format!("-{}", quote(text)),
33	            Written::Literal(Modifier::Optional, text) => quote(text),
34	            Written::Regex(text) => format!("regex:{}", quote(text)),
35	        })
36	        .collect();
37	    rendered.join(" ")
38	}
39	
40	fn expected(terms: &[Written]) -> Vec<(Modifier, String, bool)> {
41	    terms
42	        .iter()
43	        .map(|term| match term {
44	            Written::Literal(modifier, text) => (modifier.clone(), regex::escape(text), false),
45	            Written::Regex(text) => (Modifier::Optional, text.clone(), true),
46	        })
47	        .collect()
48	}
49	
50	proptest! {
51	    #[test]
52	    fn parse_never_panics_on_arbitrary_text(input in "\\PC{0,80}") {
53	        drop(parse(&input));
54	    }
55	
56	    #[test]
57	    fn parse_never_panics_on_query_shaped_text(input in "(\\+|-|regex:|\"|\\\\|[a-z.]| )*") {
58	        drop(parse(&input));
59	    }
60	
61	    #[test]
62	    fn parse_of_rendered_terms_recovers_the_terms(terms in prop::collection::vec(written(), 0..=64)) {
63	        let parsed = parse(&render(&terms)).expect("at most 64 terms");
64	        let parsed: Vec<_> = parsed.into_iter().map(|t| (t.modifier, t.pattern, t.is_regex)).collect();
65	        prop_assert_eq!(parsed, expected(&terms));
66	    }
67	}
