9	fn block_strategy() -> impl Strategy<Value = RankedBlock> {
10	    (prop::sample::select(vec!["a.ts", "b.ts", "c/d.ts"]), 0usize..14, 0usize..14, 0usize..100).prop_map(
11	        |(file, line_start, line_end, rank)| RankedBlock {
12	            block: CodeBlock {
13	                file: Utf8PathBuf::from(file),
14	                line_start,
15	                line_end,
16	                node_kind: SymbolKind::Function,
17	                code: String::new(),
18	                symbol_signature: None,
19	                matched_lines: Vec::new(),
20	                matched_keywords: Vec::new(),
21	            },
22	            bm25_score: 0.0,
23	            coverage_boost: 0.0,
24	            node_type_boost: 1.5,
25	            final_score: 0.0,
26	            rank,
27	            parent_context: None,
28	        },
29	    )
30	}
31	
32	/// The lines a block covers, empty for an inverted range.
33	fn lines(block: &RankedBlock) -> BTreeSet<usize> {
34	    (block.block.line_start..=block.block.line_end).collect()
35	}
36	
37	/// Set-based restatement of the rule: a block is dropped when it shares more than half of the smaller block's lines
38	/// with a block already kept in the same file.
39	fn reference(blocks: &[RankedBlock]) -> Vec<(Utf8PathBuf, usize, usize, usize)> {
40	    let mut kept: Vec<&RankedBlock> = Vec::new();
41	    for candidate in blocks {
42	        let candidate_lines = lines(candidate);
43	        let duplicate = kept.iter().any(|earlier| {
44	            let earlier_lines = lines(earlier);
45	            let shared = earlier_lines.intersection(&candidate_lines).count();
46	            let smaller = earlier_lines.len().min(candidate_lines.len());
47	            earlier.block.file == candidate.block.file && smaller > 0 && shared * 2 > smaller
48	        });
49	        if !duplicate {
50	            kept.push(candidate);
51	        }
52	    }
53	    kept.iter()
54	        .enumerate()
55	        .map(|(idx, r)| (r.block.file.clone(), r.block.line_start, r.block.line_end, idx + 1))
56	        .collect()
57	}
58	
59	proptest! {
60	    #[test]
61	    fn dedup_blocks_matches_the_set_based_reference(blocks in prop::collection::vec(block_strategy(), 0..24)) {
62	        let expected = reference(&blocks);
63	        let actual: Vec<_> = dedup_blocks(blocks)
64	            .iter()
65	            .map(|r| (r.block.file.clone(), r.block.line_start, r.block.line_end, r.rank))
66	            .collect();
67	        prop_assert_eq!(actual, expected);
68	    }
69	}
