877	fn enum_declaration_block<'a>(src: &'a str, decl: &str) -> &'a str {
878	    let start = src.find(decl).unwrap_or_else(|| panic!("declaration `{decl}` not found in types.rs"));
879	    let open = src[start..].find('{').unwrap_or_else(|| panic!("no opening brace found for `{decl}`")) + start;
880	    let mut depth = 0usize;
881	    for (i, ch) in src[open..].char_indices() {
882	        match ch {
883	            '{' => depth += 1,
884	            '}' => {
885	                depth -= 1;
886	                if depth == 0 {
887	                    return &src[open..=open + i];
888	                }
889	            }
890	            _ => {}
891	        }
892	    }
893	    panic!("no matching closing brace found for `{decl}`");
894	}
