896	/// Asserts that each name appears in `block` after the previous one.
897	///
898	/// Enums with data-carrying variants cannot be cast to a discriminant, so their declaration order is checked in the
899	/// source text instead.
900	fn assert_declaration_order(block: &str, variants_in_order: &[&str]) {
901	    let mut last_end = 0usize;
902	    for name in variants_in_order {
903	        let found = block[last_end..].find(name).unwrap_or_else(|| {
904	            panic!("variant `{name}` not found after position {last_end} -- out of declaration order or missing")
905	        });
906	        last_end += found + name.len();
907	    }
908	}
