1	//! Tokenizer for the search query language.
2	
3	/// A query token: `+`, `-`, the `regex:` prefix, a quoted string, a bare word, or end of input.
4	#[derive(Debug, Clone, PartialEq)]
5	pub enum Token {
6	    Plus,
7	    Minus,
8	    RegexPrefix,
9	    QuotedString(String),
10	    Word(String),
11	    Eof,
12	}
13	
14	/// A cursor over a query string that yields [`Token`]s.
15	pub struct Lexer<'a> {
16	    input: &'a str,
17	    pos: usize,
18	}
19	
20	impl<'a> Lexer<'a> {
21	    /// Creates a lexer positioned at the start of `input`.
22	    pub fn new(input: &'a str) -> Self {
23	        Self { input, pos: 0 }
24	    }
25	
26	    fn remaining(&self) -> &str {
27	        &self.input[self.pos..]
28	    }
29	
30	    fn peek(&self) -> Option<char> {
31	        self.remaining().chars().next()
32	    }
33	
34	    fn advance(&mut self) -> Option<char> {
35	        let ch = self.peek()?;
36	        self.pos += ch.len_utf8();
37	        Some(ch)
38	    }
39	
40	    fn skip_whitespace(&mut self) {
41	        while let Some(ch) = self.peek() {
42	            if ch.is_ascii_whitespace() {
43	                self.pos += ch.len_utf8();
44	            } else {
45	                break;
46	            }
47	        }
48	    }
49	
50	    fn read_word(&mut self) -> String {
51	        let mut s = String::new();
52	        loop {
53	            match self.peek() {
54	                None => break,
55	                Some(ch) if ch.is_ascii_whitespace() => break,
56	                Some(ch) => {
57	                    s.push(ch);
58	                    self.pos += ch.len_utf8();
59	                }
60	            }
61	        }
62	        s
63	    }
64	
65	    // Only `\"` is an escape; any other backslash is kept literally. An unterminated string ends silently at EOF.
66	    fn read_quoted(&mut self) -> String {
67	        let mut s = String::new();
68	        loop {
69	            match self.advance() {
70	                None | Some('"') => break,
71	                Some('\\') => match self.peek() {
72	                    Some('"') => {
73	                        self.pos += 1;
74	                        s.push('"');
75	                    }
76	                    _ => s.push('\\'),
77	                },
78	                Some(ch) => s.push(ch),
79	            }
80	        }
81	        s
82	    }
83	
84	    /// Returns the next token, or [`Token::Eof`] once the input is exhausted.
85	    pub fn next_token(&mut self) -> Token {
86	        self.skip_whitespace();
87	        match self.peek() {
88	            None => Token::Eof,
89	            Some('+') => {
90	                self.pos += 1;
91	                Token::Plus
92	            }
93	            Some('-') => {
94	                self.pos += 1;
95	                Token::Minus
96	            }
97	            Some('"') => {
98	                self.pos += 1;
99	                Token::QuotedString(self.read_quoted())
100	            }
101	            Some(_) => {
102	                if self.remaining().starts_with("regex:") {
103	                    self.pos += "regex:".len();
104	                    Token::RegexPrefix
105	                } else {
106	                    Token::Word(self.read_word())
107	                }
108	            }
109	        }
110	    }
111	}
