364	                field_block.find(&needle).unwrap_or_else(|| panic!("field `{field}` not found in Lexer struct body"));
365	            let line_start = field_block[..idx].rfind('\n').map_or(0, |p| p + 1);
366	            let line_end = field_block[idx..].find('\n').map_or(field_block.len(), |p| idx + p);
367	            let line = field_block[line_start..line_end].trim_start();
368	            assert!(
369	                line.starts_with(&needle),
370	                "Lexer.{field} must be private, found line {line:?} not starting with `{needle}` -- a pub/pub(crate)/pub(super) modifier would prefix it"
371	            );
372	        }
373	    }
