375	    // Reads the source because no compile-time check can prove a method is uncallable from outside the module.
376	    #[test]
377	    fn lexer_helper_methods_are_private_structural() {
378	        let src = include_str!("lexer.rs");
379	        for name in ["remaining", "peek", "advance", "skip_whitespace", "read_word", "read_quoted"] {
380	            let needle = format!("fn {name}");
381	            let idx = src.find(&needle).unwrap_or_else(|| panic!("helper method `{name}` not found in lexer.rs"));
382	            let line_start = src[..idx].rfind('\n').map_or(0, |p| p + 1);
383	            let line_end = src[idx..].find('\n').map_or(src.len(), |p| idx + p);
384	            let line = src[line_start..line_end].trim_start();
385	            assert!(
386	                line.starts_with("fn "),
387	                "helper method `{name}` is not declared with a bare `fn ` prefix (found line {line:?}); it must be private, not pub/pub(crate)/pub(super)"
388	            );
389	        }
390	        assert!(src.contains("pub fn new"));
391	        assert!(src.contains("pub fn next_token"));
392	    }
393	
394	    // The per-name check above misses a newly added public method, a second impl block, and `pub(crate)`. This scans
395	    // every `impl ... Lexer ... {` block, whatever its lifetime spelling, brace-matching each one, and requires the
396	    // `pub`-prefixed methods across all of them to be exactly `new` and `next_token`.
397	    #[test]
398	    fn lexer_exactly_two_public_methods_structural() {
399	        let src = include_str!("lexer.rs");
400	
401	        let mut pub_fn_lines: Vec<String> = Vec::new();
402	        let mut occurrences = 0;
403	        let mut byte_offset = 0usize;
404	        for line in src.split_inclusive('\n') {
405	            let trimmed = line.trim();
406	            let is_lexer_impl_decl = trimmed.starts_with("impl") && trimmed.contains("Lexer") && trimmed.ends_with('{');
407	            let line_len = line.len();
408	            if !is_lexer_impl_decl {
409	                byte_offset += line_len;
410	                continue;
411	            }
412	            occurrences += 1;
413	            let brace_rel = line
414	                .rfind('{')
415	                .unwrap_or_else(|| panic!("line matched as an impl-block decl but has no `{{`: {line:?}"));
416	            let open = byte_offset + brace_rel;
417	            byte_offset += line_len;
418	            debug_assert_eq!(&src[open..=open], "{");
419	
420	            let mut depth: i32 = 0;
421	            let mut close = None;
422	            for (i, ch) in src[open..].char_indices() {
423	                match ch {
424	                    '{' => depth += 1,
425	                    '}' => {
426	                        depth -= 1;
427	                        if depth == 0 {
428	                            close = Some(open + i);
429	                            break;
430	                        }
431	                    }
432	                    _ => {}
433	                }
434	            }
435	            let close =
436	                close.unwrap_or_else(|| panic!("no matching close brace found for impl block starting at byte {open}"));
437	            let block = &src[open..=close];
438	
439	            for l in block.lines() {
440	                let trimmed = l.trim_start();
441	                if trimmed.starts_with("pub") && trimmed.contains("fn ") {
442	                    let fn_pos = trimmed.find("fn ").unwrap_or_else(|| {
443	                        panic!("`contains(\"fn \")` true but `find(\"fn \")` failed for line {trimmed:?}")
444	                    });
445	                    let paren_rel = trimmed[fn_pos..].find('(').unwrap_or(trimmed.len() - fn_pos);
446	                    pub_fn_lines.push(trimmed[..fn_pos + paren_rel].trim_end().to_string());
447	                }
448	            }
449	        }
450	        assert!(occurrences > 0, "no `impl ... Lexer ... {{` block found in lexer.rs");
451	
452	        assert_eq!(pub_fn_lines, vec!["pub fn new".to_string(), "pub fn next_token".to_string()]);
453	    }
