2515	/// Asserts that the fields appear in order in `block` and that no `#[serde(` attribute precedes any of them.
2516	///
2517	/// Checking the source catches every kind of field-level serde attribute, where a behavioral test can only rule out
2518	/// the one attribute it exercises.
2519	fn assert_no_field_level_serde_attribute(block: &str, fields_in_order: &[&str]) {
2520	    let mut cursor = 0usize;
2521	    for field in fields_in_order {
2522	        let needle = format!("pub {field}:");
2523	        let field_start = block[cursor..]
2524	            .find(&needle)
2525	            .unwrap_or_else(|| panic!("field `{field}` not found after position {cursor} in declaration block"))
2526	            + cursor;
2527	        let preceding = &block[cursor..field_start];
2528	        assert!(
2529	            !preceding.contains("#[serde("),
2530	            "field `{field}` is preceded by a `#[serde(` attribute -- expected none, found in: {preceding:?}"
2531	        );
2532	        cursor = field_start + needle.len();
2533	    }
2534	}
